import{_ as t,o,c as a,a0 as s}from"./chunks/framework.D4fUSYzX.js";const d="/my-little-software-factory/assets/main-view.Cw4ACC3L.png",w=JSON.parse(`{"title":"Main view","description":"The Main view's three sections and its counts, the keys you drive it with, and what the badges mean.","frontmatter":{"title":"Main view","description":"The Main view's three sections and its counts, the keys you drive it with, and what the badges mean."},"headers":[],"relativePath":"operation/main-view.md","filePath":"operation/main-view.md"}`),n={name:"operation/main-view.md"};function i(r,e,h,c,l,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="main-view" tabindex="-1">Main view <a class="header-anchor" href="#main-view" aria-label="Permalink to &quot;Main view&quot;">​</a></h1><p><img src="'+d+`" alt="The Main view: the Ticket and Consultation sections on the left, the
detail of the selected ticket on the right"></p><p>The Main view holds three list sections on the left - the Ticket section on top, the Consultation section below it, and the Work section below that - plus one detail pane on the right that shows the detail of the item the cursor holds. <code>x</code> or a click on a section header folds the section to its header row; the same toggle restores it.</p><ul><li><strong>The Ticket section</strong> lists your tickets with their state and task type. Its header shows the pipeline counts - open, running, awaiting - and, only when non-zero, the held count with its bell marker and the ignored and muted counts. A held count means a turn ended badly and the decision is yours.</li><li><strong>The Consultation section</strong> lists your Consultations. Its header shows how many wait for your answer and how many need recovery, so a Consultation that needs you is visible whether the section is open or folded.</li><li><strong>The Work section</strong> holds every start that waits for a seat: the manual starts you staged, the starts the auto-handoff adds, and the Consultation starts. Its header shows the queue depth and the <code>paused</code> word while the drain is paused. <code>+</code> and <code>-</code> move the item under the cursor toward the front or the back, <code>Delete</code> removes it, <code>p</code> pauses or resumes the drain, and Enter starts the item now, even over the limit.</li></ul><p>The detail pane shows the full detail of the selected item. On a ticket: the title, the repository, the state, the agent with its environment, model, thinking level, and context window, the task type, the handoff count against its limit, the last completion when one stands, and the source facts - the source name, the state, and the labels. On an open ticket it shows the settings <code>Enter</code> would start with; on a ticket inside a work cycle it shows the settings that handoff started with.</p><h2 id="the-keys" tabindex="-1">The keys <a class="header-anchor" href="#the-keys" aria-label="Permalink to &quot;The keys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>Hand an open ticket off; open the decision on an <code>awaiting</code> one</td></tr><tr><td><code>e</code></td><td>Open the override panel: change the handoff&#39;s settings before it starts</td></tr><tr><td><code>w</code></td><td>Close the selected ticket&#39;s work cycle, behind a confirmation</td></tr><tr><td><code>i</code></td><td>Ignore the selected ticket, or take the ignore back</td></tr><tr><td><code>u</code></td><td>Mute the source the selected ticket came in on, or take the mute back</td></tr><tr><td><code>f</code></td><td>Cycle the list filter: the active rows, the ignored, the muted, both</td></tr><tr><td><code>a</code></td><td>Toggle auto-handoff</td></tr><tr><td><code>r</code></td><td>Refresh the ticket sources and the Consultation list</td></tr><tr><td><code>g</code></td><td>Go to the selected ticket&#39;s agent pane in herdr</td></tr><tr><td><code>Tab</code></td><td>Split the ticket list into Groups, and step to the next grouping axis</td></tr><tr><td><code>Space</code></td><td>Fold or open the Group under the cursor</td></tr><tr><td><code>?</code> / <code>F1</code></td><td>Open the Key guide, from anywhere</td></tr></tbody></table><p><code>h</code>/<code>l</code> or <code>Left</code>/<code>Right</code> move between the list and the detail pane, <code>j</code>/<code>k</code> and the arrows move the selection, <code>m</code> or <code>F2</code> reads a truncated Message line, and <code>q</code> quits.</p><h2 id="the-badges" tabindex="-1">The badges <a class="header-anchor" href="#the-badges" aria-label="Permalink to &quot;The badges&quot;">​</a></h2><ul><li><code>awaiting</code>: the agent&#39;s turn settled, and the ticket waits for your decision.</li><li><code>parked</code>: the ticket sits on a state the machine offers no task for; it moves only when a label changes.</li><li><code>queued</code>: the ticket&#39;s start waits in the Work section for a seat.</li><li>A starting ticket wears an animated spinner in place of its state badge.</li><li>A <code>blocked</code> badge means the agent is waiting on your approval; a <code>missing</code> badge means the agent is gone, and the work stops there until you restart or abandon it.</li></ul><h2 id="groups" tabindex="-1">Groups <a class="header-anchor" href="#groups" aria-label="Permalink to &quot;Groups&quot;">​</a></h2><p><code>Tab</code> splits the ticket list into <strong>Groups</strong>: runs of rows that share one value of one <strong>Grouping axis</strong> - the repository, the source, the task type, the state, or the position - and one press steps to the next axis, so the flat list is always one press away. Each Group header carries its ticket count and, above zero, its held count. <code>Space</code> or a left click folds or opens the Group under the cursor. A fold hides rows, never facts: the counts and the order of work are the same with a Group open or shut. Your grouping axis stands after a restart; the folds do not.</p><h2 id="the-mouse" tabindex="-1">The mouse <a class="header-anchor" href="#the-mouse" aria-label="Permalink to &quot;The mouse&quot;">​</a></h2><p>The mouse works: a click selects a row, a drag copies the text to your clipboard, and the wheel scrolls the lists and the detail pane.</p>`,14)])])}const m=t(n,[["render",i]]);export{w as __pageData,m as default};
